class Panier:
    def __init__(self):
        self.articles = []

    def __len__(self):
        return len(self.articles)

panier_vide = Panier()
panier_plein = Panier()
panier_plein.articles = ["pomme", "pain"]

if panier_vide:
    print("Le panier vide a du contenu")
else:
    print("Le panier est vide")

if panier_plein:
    print("Le panier a du contenu")
else:
    print("Le panier est vide")
